mapper.sql:
WHERE p.deleted = 0
AND p.subject_id = #{subjectId}
AND p.target_type = #{targetType}
AND p.status = #{status}

    AND (LOWER(p.target_name) LIKE CONCAT('%', LOWER(#{keyword}), '%')
        OR LOWER(p.target_id) LIKE CONCAT('%', LOWER(#{keyword}), '%')
        OR LOWER(p.target_corp_code) LIKE CONCAT('%', LOWER(#{keyword}), '%'))
